DO $$ BEGIN CREATE TABLE public.identity_context_revision (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), version bigint NOT NULL DEFAULT 0); INSERT INTO public.identity_context_revision DEFAULT VALUES; CREATE FUNCTION public.bump_identity_context_revision() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN UPDATE public.identity_context_revision SET version=version+1 WHERE singleton=true; RETURN NULL; END $fn$; CREATE TRIGGER identity_context_users AFTER INSERT OR UPDATE OR DELETE ON public.users FOR EACH STATEMENT EXECUTE FUNCTION public.bump_identity_context_revision(); CREATE TRIGGER identity_context_identities AFTER INSERT OR UPDATE OR DELETE ON public.identities FOR EACH STATEMENT EXECUTE FUNCTION public.bump_identity_context_revision(); CREATE TRIGGER identity_context_identity_roles AFTER INSERT OR UPDATE OR DELETE ON public.identity_roles FOR EACH STATEMENT EXECUTE FUNCTION public.bump_identity_context_revision(); CREATE TRIGGER identity_context_roles AFTER INSERT OR UPDATE OR DELETE ON public.roles FOR EACH STATEMENT EXECUTE FUNCTION public.bump_identity_context_revision(); CREATE TRIGGER identity_context_role_grants AFTER INSERT OR UPDATE OR DELETE ON public.role_grants FOR EACH STATEMENT EXECUTE FUNCTION public.bump_identity_context_revision(); CREATE TRIGGER identity_context_orgs AFTER INSERT OR UPDATE OR DELETE ON public.orgs FOR EACH STATEMENT EXECUTE FUNCTION public.bump_identity_context_revision(); CREATE TRIGGER identity_context_apps AFTER INSERT OR UPDATE OR DELETE ON public.apps FOR EACH STATEMENT EXECUTE FUNCTION public.bump_identity_context_revision(); CREATE TRIGGER identity_context_features AFTER INSERT OR UPDATE OR DELETE ON public.features FOR EACH STATEMENT EXECUTE FUNCTION public.bump_identity_context_revision(); END $$;
